UPDATE `quest_template` SET `LogTitle` = 'Retribution for the Light', `LogDescription` = 'Kill $1oa demons in Gul\'rok.', `QuestDescription` = 'There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale.$B$BYou have the power needed to destroy Teron\'gor\'s demonic minions once and for all. Send them to the Twisting Nether in pieces!' WHERE `ID` = 35254;
