UPDATE `quest_template` SET `LogTitle` = 'Sanketsu, The Burning Blade', `LogDescription` = 'Bring Sanketsu, the Burning Blade, to Lieutenant Thorn at your garrison.', `QuestDescription` = 'The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it.$B$BPerhaps someone at your garrison would be interested in seeing this weapon.' WHERE `ID` = 37191;
