UPDATE `quest_template` SET `LogTitle` = 'Cymre Brightblade', `LogDescription` = 'Defeat Cymre Brightblade in a pet battle.', `QuestDescription` = 'I found some interesting artifacts on a recent dig, and I\'d love to put them through their paces to see how they would have performed in their native cultures.  Don\'t suppose you have anything small and furry that can put up a fight?' WHERE `ID` = 37201;
UPDATE `quest_template` SET `LogTitle` = 'Hemet Nesingwary Visitor Tracking Event' WHERE `ID` = 37202;
UPDATE `quest_template` SET `LogTitle` = 'Ashlei', `LogDescription` = 'Defeat Ashlei in a pet battle.', `QuestDescription` = 'I don\'t really like when my pets fight, but I love making them feel better when they\'re done.' WHERE `ID` = 37203;
UPDATE `quest_template` SET `LogTitle` = 'Gargra', `LogDescription` = 'Defeat Gargra in a pet battle.', `QuestDescription` = 'Do you wish to offer challenge?  My wolves must train to become strong.' WHERE `ID` = 37205;
