UPDATE `quest_template` SET `LogTitle` = 'A Royal Summons', `LogDescription` = 'Use the Royal Summons and follow Sky Admiral Rogers through the portal to Stormwind Harbor.', `QuestDescription` = 'Well met, $p. I have come on behalf of King Anduin Wrynn.$B$BMy crew is preparing for a special mission, and the king would like you to join us. Please review this official summons and, if you are satisfied, return with me to Stormwind Harbor.$B$B<Rogers hands you a sealed envelope.>' WHERE `ID` = 38035;
UPDATE `quest_template` SET `LogTitle` = 'Supplies From the Skies', `LogDescription` = 'Gather $1oa Skyfire First Aid Kits.', `QuestDescription` = 'Are you feeling alright? Say \'ah.\'$B$B<Mishka attempts to depress your tongue with a damp twig.>$B$BSorry... we are in desperate need of medical supplies here. The infirmary on the Skyfire was well-stocked, but it\'s all scattered to the winds now.$B$BAnything you can salvage from the wreck will save lives!' WHERE `ID` = 38036;
