UPDATE `quest_template` SET `LogTitle` = 'Missive: Assault on Socrethar\'s Rise', `LogDescription` = 'Assault the Sargerei forces at Socrethar\'s Rise in Shadowmoon Valley.', `QuestDescription` = 'Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar\'s Rise in southern Shadowmoon Valley.\n\nSocrathar\'s disciples pose a threat to draenei and our garrison alike. We need to quell them at our soonest convenience.' WHERE `ID` = 38197;
