UPDATE `quest_template` SET `LogTitle` = 'Challiane Vineyards', `LogDescription` = 'Collect the 3 parts of the Nightrose recipe.', `QuestDescription` = 'Please, outsider, help me.$b$bMy recipe for Nightrose wine was to be the toast of Queen Azshara herself. But before I could make it, the vile vintners took it from me and locked me away.$b$bPlease, recover my recipe so that I might bring it to Lady Challiane and earn the queen\'s favor.' WHERE `ID` = 38203;
UPDATE `quest_template` SET `LogTitle` = 'Making the Rounds', `LogDescription` = 'Follow Sky Admiral Rogers and prepare the Skyfire to set sail.', `QuestDescription` = 'You must be wondering what all of this is about. Please, walk with me.$B$BI have some final preparations to make before we set sail, and I know that your presence will inspire the crew.' WHERE `ID` = 38206;
