UPDATE `quest_template` SET `LogTitle` = 'Get a Clue', `LogDescription` = 'Search the Ruins of Kra\'nak for clues.', `QuestDescription` = 'Aktar mentioned that in the ruins he\'s seen Sethekk, ogres, even demons, but no sign of Iskar.$b$bWe\'re going to have to go in there if we\'re to find any clues and I\'d prefer someone strong like yourself to lead the way.$b$bWell, what do you say?' WHERE `ID` = 38213;
