UPDATE `quest_template` SET `LogTitle` = 'Felbore' WHERE `ID` = 38775;
UPDATE `quest_template` SET `LogTitle` = 'Treasure: Sacrificial Blade' WHERE `ID` = 38776;
UPDATE `quest_template` SET `LogTitle` = 'Leystone Deposit Sample', `LogDescription` = 'Bring the Leystone Deposit Sample to Mama Diggs in Dalaran.', `QuestDescription` = 'This ore looks like nothing you\'ve seen before.$b$bA mystical sheen moves through the metal in complex, unpredictable patterns. Your trainer in Dalaran would certainly like to see this.' WHERE `ID` = 38777;
UPDATE `quest_template` SET `LogTitle` = 'Turn the Keys', `LogDescription` = 'Activate the Runestones within the Runewood.', `QuestDescription` = 'My roots wither... my branches die...\n\nThe Bonespeakers, they seek to silence the Runewood.  The runestones are the key...\n\nTurn the stones... release my bonds...' WHERE `ID` = 38778;
UPDATE `quest_template` SET `LogTitle` = 'Treasure: Hidden BH Chest' WHERE `ID` = 38779;
UPDATE `quest_template` SET `LogTitle` = '7.0 Val\'sharah - River - Vignette: Thondrax - TRACKING - twh' WHERE `ID` = 38780;
