UPDATE `quest_template` SET `LogTitle` = 'Cut Out the Heart', `LogDescription` = 'Kill Apothecary Curseheart in the Dread-Rider Incursion.', `QuestDescription` = 'This map points out the strategic locations of the Forsaken forces around Greywatch. A marker to the east indicates an apothecary camp where Dread-Riders are being supplied from.\n\nIf you were to take out the apothecary in charge of creating this plague, it could stem the invasion and prevent the Dread-Riders from spreading the plague any further.' WHERE `ID` = 39472;
