UPDATE `quest_template` SET `LogTitle` = 'Fish Out of Water', `LogDescription` = 'Return $1oa Whitewater Carp to the river.', `QuestDescription` = 'The drogbar are on a rampage! They\'re smashing everything they can find and are throwing fish to the shore.\n\nWorst of all, it is the wrong time to harvest fish. They must be returned to the waters so they can breed.' WHERE `ID` = 39614;
