UPDATE `quest_template` SET `LogTitle` = 'Well Spent Time', `LogDescription` = 'Tell Namha of your time with the tauren in Highmountain.', `QuestDescription` = 'Your respect for our ways has earned you all the knowledge we have to teach. Go now, $n, and spread our ways to those who fight against the legion.$b$bPerhaps it will help to turn the tide in this war for our world.' WHERE `ID` = 40415;
