UPDATE `quest_template` SET `LogTitle` = 'Ulthalesh, the Deadwind Harvester', `LogDescription` = 'Start your search for the Deadwind Harvester at Manor Mistmantle in Duskwood.', `QuestDescription` = 'The book says the Dark Riders were last seen in a place called Manor Mistmantle. If friend can find these riders, then $Ghe:she; can get Ulthalesh!\n\nCalydus will wait here and await your return. Find Ulthalesh, friend!' WHERE `ID` = 40495;
