UPDATE `quest_template` SET `LogTitle` = 'Mangelrath', `LogDescription` = 'Defeat Mangelrath.', `QuestDescription` = 'The demonic beast that stands before ye, must be the one that devoured ol\' Brambley...$b$bJust look at it, lying there with a full belly! I canna abide it any longer, $n! We must slay the foul creature and avenge Brambley!$b$bWe\'ve come this far already, $c.$b$bAre ye with me?!' WHERE `ID` = 41309;
