UPDATE `quest_template` SET `LogTitle` = 'In Deep Slumber', `LogDescription` = 'Enter the Emerald Dream and retrieve G\'Hanir.', `QuestDescription` = 'This bed will be yours for the deep slumber that will usher you into the Dream.$B$BOnce you are comfortable, drink of the moonwater you brought. I will guide you from there.$B$BQuickly, now - with every passing moment G\'Hanir slips further into darkness.' WHERE `ID` = 41436;
