UPDATE `quest_template` SET `LogTitle` = 'Squid Out of Water', `LogDescription` = 'Destroy 5 Willbreaker Incubators in the Sashj\'tar Ruins.', `QuestDescription` = 'Toryl told me about those squid creatures that are controlling my brothers.$B$BI have never seen anything like them before around Jandvik. The naga must have brought them from wherever they came.$B$BI do not want any more of my kin to suffer the fate of being controlled by the naga.$B$BFind out where those squids come from and stop them.' WHERE `ID` = 41499;
