UPDATE `quest_template` SET `LogTitle` = 'Finding Brytag', `LogDescription` = 'Locate Brytag in Azuregale Bay.', `QuestDescription` = '<Kell barely manages to speak.>$B$BThat naga witch... has given many of my kin... to the sea giants.$B$BBrytag was... the last one I saw alive.$B$BFind him quickly.' WHERE `ID` = 41606;
UPDATE `quest_template` SET `LogTitle` = 'Taking a Promenade', `LogDescription` = 'Locate the scouts in the Promenade.', `QuestDescription` = 'We must learn much about our long-lost kin if we are to fight them.$b$bWe dispatched one of our scouts to infiltrate the Promenade and gather intelligence. The Sentinels sent their own scout as well, hopefully she is smart enough to not get herself killed before reporting in.$b$bThey have not returned in some time, and we must suspect the worst.$b$bFind them and we shall see what we are up against.', `AreaDescription` = 'Locate the scouts in the Promenade.' WHERE `ID` = 41607;
