UPDATE `quest_template` SET `LogTitle` = 'The Seawarden', `LogDescription` = 'Kill Seawarden Largush in Azuregale Bay.', `QuestDescription` = 'The Seawarden made a deal with the Tidemistress. She handed us over to him like cattle.$B$BI despise that sea giant! If I were not trapped in this bubble, I would choke the life out of him with my own two hands.$B$BIf you cross his path before I get out of here, make him regret ever making a deal with the naga!' WHERE `ID` = 41618;
