UPDATE `quest_template` SET `LogTitle` = 'Written in Stone', `LogDescription` = 'Retrieve the Spellstone of Kel\'danath.', `QuestDescription` = '<You bundle the notes and store them away in your pack.\n\nAccording to his final journal entry, Kel\'danath used something called a "spellstone" in his experiments.\n\nThe spellstone, if not the arcanist himself, must be nearby.>' WHERE `ID` = 41702;
