UPDATE `quest_template` SET `LogTitle` = 'Subject 16', `LogDescription` = 'Deliver Theryn to Thalyssra.', `QuestDescription` = '<It seems Theryn is still under the arcanist\'s spell. In the absence of Kel\'danath himself, a live subject could be useful in helping Thalyssra unravel his research.>' WHERE `ID` = 41704;
