UPDATE `quest_template` SET `LogTitle` = 'Return to the Chamber of Shadows', `LogDescription` = 'Speak with Lord Jorach Ravenholdt in the Chamber of Shadows.', `QuestDescription` = 'Lord Jorach Ravenholdt sent me out to find you, $n. He wants your counsel on some matter of importance.\n\nHe requests your presence back at the Chamber of Shadows.', `PortraitGiverText` = 'Return to me in the Chamber of Shadows at your earliest convenience.', `PortraitGiverName` = 'Lord Jorach Ravenholdt' WHERE `ID` = 43007;
