UPDATE `quest_template` SET `LogTitle` = 'A Time to Reflect', `LogDescription` = 'Correctly answer one of Ju\'Pa\'s questions about the history of Azeroth.', `QuestDescription` = 'It is time to reflect on the events that have brought us to this moment. A celebration of our great history and the events that shape it.' WHERE `ID` = 43461;
UPDATE `quest_template` SET `LogTitle` = 'Mother Ozram', `LogDescription` = 'Kill Mother Ozram.', `QuestDescription` = 'The fiendish imps in this region are an incessant pain on our allies defending the camps below.$B$BThey are the spawn of a wicked imp-mother named Mother Ozram, who has been seen on a hill to the south.$B$BDestroy her, and we will end her brood as well.', `PortraitGiverName` = 'Mother Ozram' WHERE `ID` = 43462;
