UPDATE `quest_template` SET `LogTitle` = 'Your Fullest Potential', `LogDescription` = 'Speak with Aggra to choose a third artifact to pursue.', `QuestDescription` = 'I see that you walk many paths, as a true shaman should.$b$bTwo mighty artifacts are already in your possession. To seek a third would not be greed: it would be the fulfillment of your destiny, the completion of a circle.$b$bSpeak with me, and together we will unlock your fullest potential.' WHERE `ID` = 44006;
