UPDATE `quest_template` SET `LogTitle` = 'Bolstering Your Arsenal', `LogDescription` = 'Choose a second artifact to pursue.', `QuestDescription` = 'Highlord, there are still weapons that you might obtain to help you defeat the Legion. We have kept a close eye on them during your time on the Broken Isles.$B$BI would be happy to review them with you if you wish.' WHERE `ID` = 44063;
