UPDATE `quest_template` SET `LogTitle` = 'Champion Armaments', `LogDescription` = 'Place a workorder for Champion armaments and equipment.', `QuestDescription` = 'People today see a dead body and they just think its a smelly pile of goo, not me I tell ya. I see it as a little present holding wonderful secrets.  \n\nFor a price, Ill share those secrets with you too.' WHERE `ID` = 44231;
