UPDATE `quest_template` SET `LogTitle` = 'Vault of the Wardens', `LogDescription` = 'Defeat Cordana Felsong in Vault of the Wardens.', `QuestDescription` = 'It\'s worse than we thought within the Vault of the Wardens. The prisoners have become the jailers, and have completely taken over the vault. However, our intelligence reports that Cordana Felsong herself may be there.\n\nEnter the Vault of the Wardens and cleanse the place of evil.' WHERE `ID` = 44260;
