UPDATE `quest_template` SET `LogTitle` = 'The Arcway', `LogDescription` = 'Defeat Advisor Vandros in The Arcway.', `QuestDescription` = 'The Arcway is even more vast than we thought, and holds many dangers. If we have any hope of taking the city, we must first see to the underground.\n\nEnter The Arcway and clear out any, and all enemies.' WHERE `ID` = 44262;
