UPDATE `quest_template` SET `LogTitle` = 'Neltharion\'s Lair', `LogDescription` = 'Defeat Dargrul in Neltharion\'s Lair.', `QuestDescription` = 'Our scouts found that not only have the drogbar obtained a Titan relic, but also they\'ve amassed an army large enough to threaten the overworld.\n\nDelve underground and stop the Underking before he can unleash the might of his drogbar army.' WHERE `ID` = 44264;
