UPDATE `quest_template` SET `LogTitle` = 'Eye of Azshara', `LogDescription` = 'Defeat the Wrath of Azshara in Eye of Azshara.', `QuestDescription` = 'Our investigation found that the naga, under the orders of Queen Azshara herself, are preparing to summon a powerful entity to unleash Azshara\'s power across the Broken Isles.\n\nTravel to the Eye of Azshara, and put a stop to the ritual.' WHERE `ID` = 44270;
