UPDATE `quest_template` SET `LogTitle` = 'Darkheart Thicket', `LogDescription` = 'Defeat the Shade of Xavius in Darkheart Thicket.', `QuestDescription` = 'Beneath the boughs of Shaladrassil, Xavius extends his power to twist and torment the once-pure druid grove. \n\nNot only this, but Xavius has taken a prize from among the druids, and his revenge will be slow and painful. We should go to Darkheart Thicket and stop his wicked plans.' WHERE `ID` = 44272;
