UPDATE `quest_template` SET `LogTitle` = 'Court of Stars', `LogDescription` = 'Defeat Advisor Melandrus in Court of Stars.', `QuestDescription` = 'The weather is perfect for a party, isn\'t it?\n\nTravel to the Court of Stars, where the Grand Magistrix herself may appear among her nobles to reassure them of the need for all the Legion patrols.' WHERE `ID` = 44274;
