UPDATE `quest_template` SET `LogTitle` = 'Direbeak Reunion', `LogDescription` = 'Return the Direbeak Hatchling to Gull Rock in Stormheim.', `QuestDescription` = '<Your direbeak hatchling won\'t stop emitting soft, melancholy squawks. It seems to be depressed. Perhaps it is time to return it to its place of origin?>' WHERE `ID` = 44988;
UPDATE `quest_template` SET `LogTitle` = 'Raising Your Sharptalon', `LogDescription` = 'Raise your Sharptalon Hatchling to level 25.', `QuestDescription` = '<Your sharptalon hatchling continues to shiver as it settles in at your side. It looks up at you with wide, unblinking eyes. It appears to be looking to you to help it survive and grow.>', `PortraitGiverText` = 'Erk?', `PortraitGiverName` = 'Sharptalon Hatchling' WHERE `ID` = 44989;
