UPDATE `quest_template` SET `LogTitle` = 'Treasure 034 - Beach Pole' WHERE `ID` = 45249;
UPDATE `quest_template` SET `LogTitle` = 'Treasure 035 - Dead Tree' WHERE `ID` = 45250;
UPDATE `quest_template` SET `LogTitle` = 'Redundancy', `LogDescription` = 'Meet Aethas on the Broken Shore.', `QuestDescription` = 'A construct progenitor? What a creative solution to our problem!\n\nWe probably could channel Kathra\'natir\'s power without releasing him now, but I want to add another layer of protection before we try, just in case. I will not have anyone accusing me of subterfuge!\n\nMeet me on the Broken Shore when you are ready.', `QuestCompletionLog` = 'Meet Aethas on the Broken Shore.' WHERE `ID` = 45251;
UPDATE `quest_template` SET `LogTitle` = 'Treasure 037 - Above Lost Temple' WHERE `ID` = 45252;
