UPDATE `quest_template` SET `LogTitle` = 'Operation: Portals', `LogDescription` = 'Close 3 Legion portals.', `QuestDescription` = 'This is a serious invasion, but nothing a Slayer like you can\'t handle. Time to put those weapons to work!' WHERE `ID` = 45329;
UPDATE `quest_template` SET `LogTitle` = 'Scouting Party', `LogDescription` = 'Find Lady S\'theno and 10 Illidari Scouts.', `QuestDescription` = 'We will have our work cut out for us finding the missing scouts and Lady S\'theno. I suspect that one does not wish to be found.\n\nDo your best, $n!' WHERE `ID` = 45330;
UPDATE `quest_template` SET `LogTitle` = 'Return to Acherus', `LogDescription` = 'Return to Highlord Darion Mograine in Acherus.', `QuestDescription` = 'You\'ve grown a lot since we last met, $n. Now that we have the harness, let\'s see if Mograine has a plan to use it.' WHERE `ID` = 45331;
