UPDATE `quest_template` SET `LogTitle` = 'Defense of the Fel Hammer', `LogDescription` = 'Use the Illidari Gateway to return to the Fel Hammer.', `QuestDescription` = 'We need to get back to the Fel Hammer ASAP!' WHERE `ID` = 45339;
