UPDATE `quest_template` SET `LogTitle` = 'Pearl of Fathoms', `LogDescription` = 'Bring the Pearl of Fathoms to Warlord Gorchuk in Silithus.', `QuestDescription` = 'The pearl is immaculately smooth, and surprisingly dense.' WHERE `ID` = 45748;
UPDATE `quest_template` SET `LogTitle` = 'Salt of Shards', `LogDescription` = 'Bring the Salt of Shards to Warlord Gorchuk in Silithus.', `QuestDescription` = 'The Abyssal Lord left behind a small pile of faintly-iridescent sand.' WHERE `ID` = 45749;
UPDATE `quest_template` SET `LogTitle` = 'Song of Zephyrs', `LogDescription` = 'Bring the Song of Zephyrs to Warlord Gorchuk in Silithus.', `QuestDescription` = 'A swirling essence coalesces at the feet of the Duke.' WHERE `ID` = 45750;
UPDATE `quest_template` SET `LogTitle` = 'Coreforged Sigil of Skaldrenox', `LogDescription` = 'Bring the Coreforged Sigil of Skaldrenox to Warlord Gorchuk in Silithus.', `QuestDescription` = 'The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was forged in flame.' WHERE `ID` = 45751;
UPDATE `quest_template` SET `LogTitle` = 'Glimmering Sigil of Whirlaxis', `LogDescription` = 'Bring the Glimmering Sigil of Whirlaxis to Warlord Gorchuk in Silithus.', `QuestDescription` = 'The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved with biting winds.' WHERE `ID` = 45752;
UPDATE `quest_template` SET `LogTitle` = 'Diamondine Sigil of Kazum', `LogDescription` = 'Bring the Diamondine Sigil of Kazum to Warlord Gorchuk in Silithus.', `QuestDescription` = 'The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved from stone, then fused into a faultless diamond.' WHERE `ID` = 45753;
UPDATE `quest_template` SET `LogTitle` = 'Tidal Sigil of Skwol', `LogDescription` = 'Bring the Tidal Sigil of Skwol to Warlord Gorchuk in Silithus.', `QuestDescription` = 'The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was crafted from coral and smoothed by the tides.' WHERE `ID` = 45754;
