UPDATE `quest_template` SET `LogTitle` = 'Call of the Scarab', `LogDescription` = 'Report to Warlord Gorchuk in Silithus.', `QuestDescription` = 'The Call of the Scarab event is occurring today. Speak with your faction\'s leader near the Gates of Ahn\'Qiraj.' WHERE `ID` = 45785;
UPDATE `quest_template` SET `LogTitle` = 'Feast of the Hounds' WHERE `ID` = 45786;
