UPDATE `quest_template` SET `LogTitle` = 'Dread Infiltrators', `LogDescription` = 'Speak with Lilian Voss in the Hall of Shadows.', `QuestDescription` = 'Shadowblade, we have received a raven with most troubling news.\n\nOne of our own, an ally that walked our very Hall of Shadows, is not who they seem.\n\nI believe Lilian has already begun dissecting their corpse. You\'d best hurry.' WHERE `ID` = 46103;
