UPDATE `quest_template` SET `LogTitle` = 'Thwarting the Twins', `LogDescription` = 'Speak with War Councilor Victoria to be teleported to Raest\'s location and defeat him.', `QuestDescription` = 'I have news from Archmage Karlain! The Kirin Tor have found Raest Magespear and can open up a portal to his location!\n\nIf you are ready to face him, I can have the mages here open the portal into the Twisting Nether.' WHERE `ID` = 46127;
