UPDATE `quest_template` SET `LogTitle` = 'Sterile Surroundings', `LogDescription` = 'Return to Netherlight Temple.', `QuestDescription` = 'With the threat of infection dismissed, your allies should be able to press their assault here on the Broken Shore and gain an advantage over the Burning Legion.\n\nLet\'s leave this place and speak somewhere more... sterile. I hear your order occupies an impressive temple.' WHERE `ID` = 46145;
