UPDATE `quest_template` SET `LogTitle` = 'Meld Into the Shadows', `LogDescription` = 'Return to the Hall of Shadows, and meet Lord Jorach Ravenholdt.', `QuestDescription` = 'We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.' WHERE `ID` = 46827;
