UPDATE `quest_template` SET `LogTitle` = 'Alone in the Abyss', `LogDescription` = 'Speak to Grand Artificer Romuul to disembark the Vindicaar.', `QuestDescription` = 'Champion, we will suffer the same fate as the Army of the Light if the Legion fires that infernal weapon upon us.$B$BWe must descend into the siege camp below and destroy it while we still can!', `QuestCompletionLog` = 'Meet Prophet Velen at Darkfall Ridge.' WHERE `ID` = 46938;
