UPDATE `quest_template` SET `LogTitle` = 'Lost Souls', `LogDescription` = 'Release $1oa Lost Souls.', `QuestDescription` = 'Never in my life have I beheld such destruction... such misery. The very ground we walk on us paved with the bones of our allies.\n\nEven now I can see the lost spirits of Alliance soldiers wandering the ruins.\n\nI cannot leave this place without putting the souls of our brave soldiers to rest. We owe them... I owe them that much.' WHERE `ID` = 47112;
