UPDATE `quest_template` SET `LogTitle` = 'Antoran High Command', `LogDescription` = 'Defeat the Antoran High Command in Antorus, the Burning Throne.', `QuestDescription` = 'The Legion has spent over 10,000 years planning their invasion of Azeroth. Defeat their leaders so they can never threaten our world again.' WHERE `ID` = 48288;
UPDATE `quest_template` SET `LogTitle` = 'The Soulhunter', `LogDescription` = 'Defeat Imonar the Soulhunter in Antorus, the Burning Throne.', `QuestDescription` = 'Imonar is the deadliest bounty hunter the Twisting Nether has ever produced. Find a pit to throw him down.' WHERE `ID` = 48292;
UPDATE `quest_template` SET `LogTitle` = 'The Burning Coven', `LogDescription` = 'Defeat the Coven of Shivarra in Antorus, the Burning Throne.', `QuestDescription` = 'Not even a Titan can endure their torture. Bring an end to the Coven of Shivarra.' WHERE `ID` = 48293;
UPDATE `quest_template` SET `LogTitle` = 'The Unmaker', `LogDescription` = 'Defeat Argus the Unmaker in Antorus, the Burning Throne.', `QuestDescription` = 'Argus is Sargeras\' solution for existence; an end to all things. For everyone that might ever live, bring an end to the Unmaker.' WHERE `ID` = 48294;
