UPDATE `quest_template` SET `LogTitle` = 'Further Supplying Krokuun', `LogDescription` = 'Collect $1oa Order Hall Resources.', `QuestDescription` = 'This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker.\n\nWhat say you, offworlder?' WHERE `ID` = 48634;
